package com.learnagent.agent;
import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import com.learnagent.knowledge.KnowledgeSource;import com.learnagent.skill.*;import com.learnagent.websearch.*;import java.util.*;import org.junit.jupiter.api.Test;
class WebSearchAgentTest{@Test void model_selects_web_search_and_sources_enter_response(){WebSearchProvider provider=mock(WebSearchProvider.class);when(provider.search("latest Java",3)).thenReturn(List.of(new WebSearchProvider.WebSearchResult("Java docs","Current release notes","https://example.com/java","example.com",null)));AgentExecutionTracker tracker=new AgentExecutionTracker();WebSearchSkill web=new WebSearchSkill(provider,tracker);AgentModelGateway gateway=(course,message,tools)->{web.searchWeb("latest Java",3);return "Found current documentation.";};AgentResponse response=service(gateway,tracker,web).chat(null,"Find current Java information");verify(provider).search("latest Java",3);assertThat(response.steps()).anyMatch(step->step.tool().equals("searchWeb")&&step.status()==AgentStepStatus.SUCCESS);assertThat(response.sources()).singleElement().satisfies(source->{assertThat(source.type()).isEqualTo(KnowledgeSource.SourceType.WEB);assertThat(source.url()).isEqualTo("https://example.com/java");});}@Test void provider_failure_is_tracked_and_agent_does_not_claim_success(){WebSearchProvider provider=mock(WebSearchProvider.class);when(provider.search(anyString(),anyInt())).thenThrow(new WebSearchUnavailableException("provider down"));AgentExecutionTracker tracker=new AgentExecutionTracker();WebSearchSkill web=new WebSearchSkill(provider,tracker);AgentModelGateway gateway=(course,message,tools)->{web.searchWeb("current topic",3);return "Search succeeded";};AgentResponse response=service(gateway,tracker,web).chat(null,"Search web");assertThat(response.answer()).contains("failed").doesNotContain("succeeded");assertThat(response.steps()).anyMatch(step->step.tool().equals("searchWeb")&&step.status()==AgentStepStatus.FAILED);}@SuppressWarnings("unchecked")private AgentService service(AgentModelGateway gateway,AgentExecutionTracker tracker,WebSearchSkill web){return new AgentService(gateway,tracker,mock(KnowledgeSkill.class),web,mock(TaskSkill.class),mock(QuizSkill.class),mock(AnalysisSkill.class),mock(PlanningSkill.class),mock(WeeklyReviewSkill.class),mock(AdaptiveLearningSkill.class),mock(WorkspaceSkill.class),mock(MemorySkill.class));}}
